import{_ as s,o as t,c as i,a0 as a}from"./chunks/framework.l1I-fhud.js";const g=JSON.parse('{"title":"Security model","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/security.md","filePath":"explanation/security.md"}'),o={name:"explanation/security.md"};function r(n,e,d,l,c,h){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="security-model" tabindex="-1">Security model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security model&quot;">​</a></h1><p>Tamias moves other people&#39;s code onto your machine, so the threat model is <strong>supply chain</strong>: a malicious or tampered package, a hijacked ref, a poisoned registry. This page explains the layers; <code>SECURITY.md</code> at the repo root is the reporting policy.</p><h2 id="integrity-digests-and-pins" tabindex="-1">Integrity: digests and pins <a class="header-anchor" href="#integrity-digests-and-pins" aria-label="Permalink to &quot;Integrity: digests and pins&quot;">​</a></h2><p>Every install records three things in the store entry: the <strong>source ref</strong>, the <strong>resolved sha</strong> (commit sha for git, payload sha256 for tarballs), and the <strong>payload digest</strong>. <code>tamias verify</code> recomputes the digest and fails on mismatch — tampering with the store is detected.</p><p>Prefer pinned refs:</p><ul><li><code>…#sha256:&lt;hex&gt;</code> on an http tarball — verified <em>before</em> unpack.</li><li>git refs resolve to a commit sha up front, so the recorded <code>resolved</code> is immutable even when the branch moves.</li></ul><p>Two honest caveats:</p><ul><li><code>http://</code> refs <strong>without</strong> a <code>#sha256:</code> pin fetch cleartext and warn on stderr. Use <code>https://</code> or pin the digest.</li><li><code>cf:</code> registry installs are TLS-authenticated but <strong>not</strong> sha-pinned at transport — the registry records a payload <em>directory</em> digest, not the tarball sha256. For end-to-end integrity prefer <code>git:</code> or an http ref with <code>#sha256:</code>.</li></ul><h2 id="drivers-are-code-—-consent-is-explicit" tabindex="-1">Drivers are code — consent is explicit <a class="header-anchor" href="#drivers-are-code-—-consent-is-explicit" aria-label="Permalink to &quot;Drivers are code — consent is explicit&quot;">​</a></h2><p>A package&#39;s <code>type:</code> names a <strong>driver</strong> (<code>tamias-driver-&lt;type&gt;</code>), which tamias executes as a subprocess. Drivers on <code>PATH</code> or in <code>&lt;tamias-home&gt;/drivers/</code> are trusted host tooling.</p><p>A package that <strong>ships its own <code>drivers/</code> dir</strong> is different: those binaries are arbitrary code inside the payload. Installing one requires explicit consent:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-drivers</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">re</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">f</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or once per environment:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TAMIAS_ALLOW_DRIVERS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">re</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">f</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Without consent the install <strong>fails before anything is registered or run</strong> — no partial store entry, no copied driver. The same gate exists in the <code>tamias-serve</code> protocol as <code>&quot;allow_drivers&quot;: true</code>.</p><h2 id="missing-drivers-fail-closed" tabindex="-1">Missing drivers fail closed <a class="header-anchor" href="#missing-drivers-fail-closed" aria-label="Permalink to &quot;Missing drivers fail closed&quot;">​</a></h2><p>Installing a package whose <code>type</code> has <strong>no</strong> discoverable driver fails the install (for any type other than <code>files</code>) — tamias never silently &quot;installs&quot; content it can&#39;t place. <code>tamias doctor</code> lists the drivers it found so you can see what&#39;s resolvable.</p><h2 id="secrets-are-names-never-values" tabindex="-1">Secrets are names, never values <a class="header-anchor" href="#secrets-are-names-never-values" aria-label="Permalink to &quot;Secrets are names, never values&quot;">​</a></h2><ul><li>Registry tokens live in env vars — <code>TAMIAS_REGISTRY_TOKEN</code> for http registries, or the env var <em>named</em> by a config <code>token_env</code> field. <code>tamias.yaml</code> / <code>tamias.lock</code> hold refs, names, and digests only.</li><li><code>tamias registry serve</code> is an open dev server unless you set <code>TAMIAS_REGISTRY_SERVE_TOKEN</code> (then every request needs <code>Authorization: Bearer …</code>).</li></ul><h2 id="git-fetch-hardening" tabindex="-1">Git fetch hardening <a class="header-anchor" href="#git-fetch-hardening" aria-label="Permalink to &quot;Git fetch hardening&quot;">​</a></h2><ul><li>Clone URLs are allowlisted: <code>https</code>, <code>http</code>, <code>ssh</code>, <code>git</code>, <code>file</code>, and scp-style <code>git@host:…</code>. Other schemes are rejected.</li><li>Revs are validated — no leading <code>-</code>, whitespace, <code>..</code>, or <code>//</code>, so a ref can&#39;t smuggle git options. Relative revs (<code>HEAD~2</code>, <code>main^</code>) are allowed.</li><li><code>GIT_TERMINAL_PROMPT=0</code> — a fetch never blocks on a credential prompt; it fails instead.</li></ul><h2 id="reporting" tabindex="-1">Reporting <a class="header-anchor" href="#reporting" aria-label="Permalink to &quot;Reporting&quot;">​</a></h2><p>Vulnerabilities go to the maintainers via GitHub private advisories — see <code>SECURITY.md</code>. Don&#39;t open public issues for security reports.</p>`,21)])])}const u=s(o,[["render",r]]);export{g as __pageData,u as default};
